body:
{
  "name": "spritecast",
  "version": "0.27.0",
  "description": "Game props and characters at their real size and exact camera angle, drawn in your art style - props, standing figures, and 8-direction walking characters (3D-guided).",
  "author": {
    "name": "Sunghwan Baek"
  },
  "repository": "https://github.com/Sunghwan0112/spritecast",
  "license": "MIT",
  "keywords": [
    "isometric",
    "gamedev",
    "sprites",
    "sprite-generator",
    "game-assets",
    "props",
    "characters",
    "walk-cycle",
    "image-generation",
    "claude-code"
  ],
  "userConfig": {
    "openai_api_key": {
      "type": "string",
      "title": "OpenAI API key",
      "description": "Drawing props and characters (about $0.07 a prop, $2.2 a walking character). From platform.openai.com.",
      "sensitive": true
    },
    "tripo_api_key": {
      "type": "string",
      "title": "Tripo API key (optional)",
      "description": "Walking characters and animals: the 3D model and its rig (75 / 30 credits). From platform.tripo3d.ai.",
      "sensitive": true
    },
    "meshy_api_key": {
      "type": "string",
      "title": "Meshy API key (optional)",
      "description": "Only if you choose Meshy as the 3D modeller (\"modeler\": \"meshy\").",
      "sensitive": true
    }
  }
}
